import React, { Suspense, lazy } from 'react';
import './App.css';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';

import Home from './pages';

// Route-level code splitting: only the homepage ships in the initial bundle.
// The blog reader (plus all post content) and the Homunculus page load as
// their own chunks on first navigation.
const BlogPostPage = lazy(() => import('./pages/blogPost'));
const HomunculusPage = lazy(() => import('./pages/homunculus'));
const NotFoundPage = lazy(() => import('./pages/notFound'));

function App() {
  return (
    <Router>
      <Suspense fallback={null}>
        <Routes>
          <Route path='/' element={<Home />} />
          <Route path='/blog/:slug' element={<BlogPostPage />} />
          <Route path='/homunculus' element={<HomunculusPage />} />
          {/* a real 404 (with noindex) instead of a silent redirect home —
              redirecting made every bad URL a soft-404 for crawlers and gave
              visitors no signal their link was stale */}
          <Route path='*' element={<NotFoundPage />} />
        </Routes>
      </Suspense>
    </Router>
  );
}

export default App;
